define(['underscore','Magento_Checkout/js/view/payment/default','Magento_Checkout/js/model/quote','Magento_Vault/js/view/payment/vault-enabler','PayPal_Braintree/js/applepay/button','PayPal_Braintree/js/helper/get-apple-pay-line-items'],function(_,Component,quote,VaultEnabler,button,getApplePayLineItems){'use strict';return Component.extend({defaults:{template:'PayPal_Braintree/applepay/core-checkout',paymentMethodNonce:null,deviceData:null,grandTotalAmount:0,deviceSupported:button.deviceSupported(),vaultEnabler:null,additionalData:{}},initialize:function(){this._super();this.vaultEnabler=new VaultEnabler();this.vaultEnabler.setPaymentCode(this.getVaultCode());return this;},getApplePayBtn:function(id){button.init(document.getElementById(id),this);},initObservable:function(){this._super();this.vaultEnabler=new VaultEnabler();this.vaultEnabler.setPaymentCode(this.getVaultCode());this.grandTotalAmount=parseFloat(quote.totals()['base_grand_total']).toFixed(2);quote.totals.subscribe(function(){if(this.grandTotalAmount!==quote.totals()['base_grand_total']){this.grandTotalAmount=parseFloat(quote.totals()['base_grand_total']).toFixed(2);}}.bind(this));return this;},startPlaceOrder:function(nonce,event,session,device_data){this.setPaymentMethodNonce(nonce);this.setDeviceData(device_data);this.placeOrder();session.completePayment(window.ApplePaySession.STATUS_SUCCESS);},setPaymentMethodNonce:function(nonce){this.paymentMethodNonce=nonce;},setDeviceData:function(device_data){this.deviceData=device_data;},getClientToken:function(){return window.checkoutConfig.payment[this.getCode()].clientToken;},getPriceIncludesTax:function(){return window.checkoutConfig.payment[this.getCode()].priceIncludesTax;},getPaymentRequest:function(){return{total:{label:this.getDisplayName(),amount:this.grandTotalAmount},lineItems:getApplePayLineItems(quote.totals(),this.getPriceIncludesTax())};},getDisplayName:function(){return window.checkoutConfig.payment[this.getCode()].merchantName;},getData:function(){var data={'method':this.getCode(),'additional_data':{'payment_method_nonce':this.paymentMethodNonce,'device_data':this.deviceData}};data['additional_data']=_.extend(data['additional_data'],this.additionalData);this.vaultEnabler.visitAdditionalData(data);return data;},getPaymentMarkSrc:function(){return window.checkoutConfig.payment[this.getCode()].paymentMarkSrc;},isVaultEnabled:function(){return this.vaultEnabler.isVaultEnabled();},getVaultCode:function(){return window.checkoutConfig.payment[this.getCode()].vaultCode;}});});